shapes.code:
// No classes needed: objects delegate to a shared prototype object.
const shape = {
  describe() {
    return `${this.name}: ${this.area()}`;
  },
};

function rectangle(width, height) {
  return Object.assign(Object.create(shape), {
    name: "Rectangle",
    area: () => width * height, // closes over width and height
  });
}

function triangle(base, height) {
  return Object.assign(Object.create(shape), {
    name: "Triangle",
    area: () => (base * height) / 2,
  });
}

for (const s of [rectangle(3, 4), triangle(10, 3)]) {
  console.log(s.describe());
}

signature.code:
// Closures hold private state; one event loop interleaves all async work.
function counter() {
  let n = 0; // captured, invisible outside
  return () => ++n;
}
const step = counter();

const wait = (ms, value) =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

async function main() {
  console.log(`${step()}: start`);
  setTimeout(() => console.log(`${step()}: timer callback (task queue)`), 0);
  Promise.resolve().then(() => console.log(`${step()}: promise callback (microtask)`));
  console.log(`${step()}: synchronous code always finishes first`);
  const msg = await wait(10, "resumed after await");
  console.log(`${step()}: ${msg}`);
}

main();
